extern "C" float GRandInRange(float, float);

extern "C" SMT *PsmtChooseRandom(SM *psm, int count, SMT **apsmt)
{
    float total = 0.0f;
    for (int index = 0; index < count; index++) total += apsmt[index]->g;
    total = GRandInRange(0.0f, total);
    for (int index = 0; index < count; index++) {
        total -= apsmt[index]->g;
        if (total <= 0.0f) return apsmt[index];
    }
    return 0;
}

